content:
:root {
  --bg-color: #f3f4f6;
  --calc-bg: #ffffff;
  --text-color: #1f2937;
  --title-color: #4b5563;
  --display-bg: #f9fafb;
  --display-text: #111827;

  --btn-num-bg: #f3f4f6;
  --btn-num-hover: #e5e7eb;
  --btn-num-text: #1f2937;

  --btn-op-bg: #e0e7ff;
  --btn-op-hover: #c7d2fe;
  --btn-op-text: #3730a3;

  --btn-action-bg: #fee2e2;
  --btn-action-hover: #fecaca;
  --btn-action-text: #991b1b;

  --btn-equal-bg: #4f46e5;
  --btn-equal-hover: #4338ca;
  --btn-equal-text: #ffffff;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg-color: #111827;
    --calc-bg: #1f2937;
    --text-color: #f9fafb;
    --title-color: #9ca3af;
    --display-bg: #374151;
    --display-text: #f9fafb;

    --btn-num-bg: #374151;
    --btn-num-hover: #4b5563;
    --btn-num-text: #f9fafb;

    --btn-op-bg: #312e81;
    --btn-op-hover: #3730a3;
    --btn-op-text: #e0e7ff;

    --btn-action-bg: #7f1d1d;
    --btn-action-hover: #991b1b;
    --btn-action-text: #fee2e2;

    --btn-equal-bg: #6366f1;
    --btn-equal-hover: #4f46e5;
    --btn-equal-text: #ffffff;
  }
}

body {
  margin: 0;
  padding: 16px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-color);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  box-sizing: border-box;
}

.calculator {
  background-color: var(--calc-bg);
  width: 100%;
  max-width: 380px;
  min-width: 300px;
  padding: 24px;
  border-radius: 16px;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1);
  box-sizing: border-box;
}

.calculator-title {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--title-color);
  text-align: center;
  margin-bottom: 16px;
  letter-spacing: -0.025em;
}

.display {
  background-color: var(--display-bg);
  color: var(--display-text);
  font-size: 2rem;
  font-weight: 600;
  text-align: right;
  padding: 16px;
  border-radius: 12px;
  margin-bottom: 20px;
  min-height: 48px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  overflow: hidden;
  word-break: break-all;
  box-shadow: inset 0 2px 4px 0 rgba(0, 0, 0, 0.05);
}

.keypad {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  align-content: start;
}

.btn {
  border: none;
  border-radius: 10px;
  font-size: 1.25rem;
  font-weight: 600;
  height: 56px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background-color 0.15s ease, transform 0.1s ease;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

.btn:active {
  transform: scale(0.95);
}

.btn-number {
  background-color: var(--btn-num-bg);
  color: var(--btn-num-text);
}

.btn-number:hover {
  background-color: var(--btn-num-hover);
}

.btn-operator {
  background-color: var(--btn-op-bg);
  color: var(--btn-op-text);
}

.btn-operator:hover {
  background-color: var(--btn-op-hover);
}

.btn-action {
  background-color: var(--btn-action-bg);
  color: var(--btn-action-text);
}

.btn-action:hover {
  background-color: var(--btn-action-hover);
}

.btn-equal {
  background-color: var(--btn-equal-bg);
  color: var(--btn-equal-text);
  grid-column: span 2;
}

.btn-equal:hover {
  background-color: var(--btn-equal-hover);
}

@media (max-width: 400px) {
  .calculator {
    padding: 16px;
  }
  .btn {
    height: 50px;
    font-size: 1.15rem;
  }
}

import { useState, useEffect } from 'react';

export default function App() {
  const [displayValue, setDisplayValue] = useState('0');
  const [firstOperand, setFirstOperand] = useState<number | null>(null);
  const [operator, setOperator] = useState<string | null>(null);
  const [waitingForOperand, setWaitingForOperand] = useState(false);

  const inputDigit = (digit: string) => {
    if (waitingForOperand) {
      setDisplayValue(digit);
      setWaitingForOperand(false);
    } else {
      setDisplayValue(displayValue === '0' ? digit : displayValue + digit);
    }
  };

  const inputDecimal = () => {
    if (waitingForOperand) {
      setDisplayValue('0.');
      setWaitingForOperand(false);
      return;
    }
    if (!displayValue.includes('.')) {
      setDisplayValue(displayValue + '.');
    }
  };

  const clear = () => {
    setDisplayValue('0');
    setFirstOperand(null);
    setOperator(null);
    setWaitingForOperand(false);
  };

  const calculate = (first: number, second: number, op: string) => {
    switch (op) {
      case '+':
        return first + second;
      case '-':
        return first - second;
      case '*':
        return first * second;
      case '/':
        return second === 0 ? 0 : first / second;
      default:
        return second;
    }
  };

  const performOperation = (nextOperator: string) => {
    const inputValue = parseFloat(displayValue);

    if (waitingForOperand && operator) {
      setOperator(nextOperator);
      return;
    }

    if (firstOperand === null) {
      setFirstOperand(inputValue);
    } else if (operator) {
      const result = calculate(firstOperand, inputValue, operator);
      setDisplayValue(String(result));
      setFirstOperand(result);
    }

    setWaitingForOperand(true);
    setOperator(nextOperator);
  };

  const handleEqual = () => {
    const inputValue = parseFloat(displayValue);
    if (operator && firstOperand !== null) {
      const result = calculate(firstOperand, inputValue, operator);
      setDisplayValue(String(result));
      setFirstOperand(null);
      setOperator(null);
      setWaitingForOperand(true);
    }
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key >= '0' && e.key <= '9') {
        inputDigit(e.key);
      } else if (e.key === '.') {
        inputDecimal();
      } else if (e.key === '+' || e.key === '-') {
        performOperation(e.key);
      } else if (e.key === '*') {
        performOperation('*');
      } else if (e.key === '/') {
        e.preventDefault();
        performOperation('/');
      } else if (e.key === 'Enter' || e.key === '=') {
        handleEqual();
      } else if (e.key === 'Escape' || e.key === 'c' || e.key === 'C') {
        clear();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [displayValue, firstOperand, operator, waitingForOperand]);

  return (
    <div className="calculator">
      <div className="calculator-title">電卓</div>
      <div className="display">{displayValue}</div>
      <div className="keypad">
        <button className="btn btn-action" style={{ gridColumn: 'span 3' }} onClick={clear}>C</button>
        <button className="btn btn-operator" onClick={() => performOperation('/')}>÷</button>

        <button className="btn btn-number" onClick={() => inputDigit('7')}>7</button>
        <button className="btn btn-number" onClick={() => inputDigit('8')}>8</button>
        <button className="btn btn-number" onClick={() => inputDigit('9')}>9</button>
        <button className="btn btn-operator" onClick={() => performOperation('*')}>×</button>

        <button className="btn btn-number" onClick={() => inputDigit('4')}>4</button>
        <button className="btn btn-number" onClick={() => inputDigit('5')}>5</button>
        <button className="btn btn-number" onClick={() => inputDigit('6')}>6</button>
        <button className="btn btn-operator" onClick={() => performOperation('-')}>-</button>

        <button className="btn btn-number" onClick={() => inputDigit('1')}>1</button>
        <button className="btn btn-number" onClick={() => inputDigit('2')}>2</button>
        <button className="btn btn-number" onClick={() => inputDigit('3')}>3</button>
        <button className="btn btn-operator" onClick={() => performOperation('+')}>+</button>

        <button className="btn btn-number" onClick={() => inputDigit('0')}>0</button>
        <button className="btn btn-number" onClick={inputDecimal}>.</button>
        <button className="btn btn-equal" onClick={handleEqual}>=</button>
      </div>
    </div>
  );
}
